# ── Helpers ───────────────────────────────────────────────────────────────────

_item_cache = {}
def resolve_item_code(item_name):
    """item_name → Pharmacy Item .item_code"""
    if item_name in _item_cache:
        return _item_cache[item_name]
    mapped_name = ITEM_MAP.get(item_name, item_name)
    code = frappe.db.get_value("Pharmacy Item",
                               {"item_name": mapped_name}, "item_code")
    _item_cache[item_name] = code
    return code


def ensure_customer(name):
    """Return customer name, creating a minimal record if needed."""
    if frappe.db.exists("Customer", {"customer_name": name}):
        return name
    c = frappe.get_doc({
        "doctype":        "Customer",
        "customer_name":  name,
        "customer_type":  "Individual",
        "customer_group": "Individual",
        "territory":      "India",
    })
    c.flags.ignore_permissions = True
    c.flags.ignore_mandatory   = True
    c.insert()
    return c.name


def infer_location(state, courier):
    """Pick a valid custom_location value from the courier amount."""
    if state == "Intra-State":
        if courier <= 0:
            return "OutSide Pune"
        elif abs(courier - 100) < 1:
            return "Pune"
        elif abs(courier - 200) < 1:
            return "OutSide Pune"
        else:
            return "Arranged at Place"
    else:  # Inter-State
        if courier <= 0:
            return "OutSide Maharashtra"
        elif abs(courier - 500) < 1:
            return "Air Courier"
        elif abs(courier - 250) < 1:
            return "OutSide Maharashtra"
        else:
            return "Arranged at Place"


def build_tax_rows(state, courier):
    """
    Build the Sales Taxes and Charges table exactly as CS_18 would.
    courier = net courier charge (before its own GST).

    Intra + no courier:
        SGST 2.5% | CGST 2.5% | Courier Recovery (₹0)
    Intra + courier:
        SGST 2.5% | CGST 2.5% | Courier Recovery (Actual) |
        Courier SGST 9% (On Prev Row) | Courier CGST 9% (On Prev Row)
    Inter + no courier:
        IGST 5% | Courier Recovery (₹0)
    Inter + courier:
        IGST 5% | Courier Recovery (Actual) | Courier IGST 18% (On Prev Row)
    """
    taxes = []
    if state == "Intra-State":
        taxes.append({"charge_type": "On Net Total",
                      "account_head": SGST_ACC,
                      "description": "SGST on Products",
                      "rate": 2.5, "included_in_print_rate": 0})
        taxes.append({"charge_type": "On Net Total",
                      "account_head": CGST_ACC,
                      "description": "CGST on Products",
                      "rate": 2.5, "included_in_print_rate": 0})
        if courier > 0:
            courier_row_idx = str(len(taxes) + 1)   # 1-based idx of Actual row
            taxes.append({"charge_type": "Actual",
                          "account_head": COURIER_ACC,
                          "description": "Courier Charges",
                          "tax_amount": courier,
                          "rate": 0, "included_in_print_rate": 0})
            taxes.append({"charge_type": "On Previous Row Amount",
                          "row_id": courier_row_idx,
                          "account_head": COURIER_SGST_ACC,
                          "description": "Courier SGST Payable",
                          "rate": 9, "included_in_print_rate": 0})
            taxes.append({"charge_type": "On Previous Row Amount",
                          "row_id": courier_row_idx,
                          "account_head": COURIER_CGST_ACC,
                          "description": "Courier CGST Payable",
                          "rate": 9, "included_in_print_rate": 0})
        else:
            taxes.append({"charge_type": "Actual",
                          "account_head": COURIER_ACC,
                          "description": "Courier Charges",
                          "tax_amount": 0, "rate": 0,
                          "included_in_print_rate": 0})
    else:  # Inter-State
        taxes.append({"charge_type": "On Net Total",
                      "account_head": IGST_ACC,
                      "description": "IGST on Products",
                      "rate": 5, "included_in_print_rate": 0})
        if courier > 0:
            courier_row_idx = str(len(taxes) + 1)
            taxes.append({"charge_type": "Actual",
                          "account_head": COURIER_ACC,
                          "description": "Courier Charges",
                          "tax_amount": courier,
                          "rate": 0, "included_in_print_rate": 0})
            taxes.append({"charge_type": "On Previous Row Amount",
                          "row_id": courier_row_idx,
                          "account_head": COURIER_IGST_ACC,
                          "description": "Courier IGST Payable",
                          "rate": 18, "included_in_print_rate": 0})
        else:
            taxes.append({"charge_type": "Actual",
                          "account_head": COURIER_ACC,
                          "description": "Courier Charges",
                          "tax_amount": 0, "rate": 0,
                          "included_in_print_rate": 0})
    return taxes


# ── Main ──────────────────────────────────────────────────────────────────────

def run(start=0, count=10, dry_run=0):
    start   = int(start)
    count   = int(count)
    dry_run = int(dry_run)

    batch   = INVOICES[start: start + count]
    total   = len(INVOICES)

    print(f"\n{'[DRY RUN] ' if dry_run else ''}Processing rows {start}–"
          f"{start+len(batch)-1} of {total}")
    print("=" * 60)

    ok = 0; fail = 0; created_customers = []
    results = []

    for idx, row in enumerate(batch):
        date      = row["date"]
        customer  = row["customer"]
        item_name = row["item_name"]
        qty       = flt(row["qty"])
        rate      = flt(row["rate"])
        online    = row["online"]
        state     = row["state"]
        courier   = flt(row["courier"])

        try:
            # ── Resolve item ──────────────────────────────────────────
            item_code = resolve_item_code(item_name)
            if not item_code:
                raise ValueError(f"Item '{item_name}' not found in Pharmacy Items")

            # ── Customer ──────────────────────────────────────────────
            cust_name = None
            if not dry_run:
                cust_name = ensure_customer(customer)
                if cust_name and not frappe.db.exists(
                        "Customer", {"customer_name": customer}):
                    created_customers.append(customer)
            else:
                cust_name = customer

            # ── Location ──────────────────────────────────────────────
            location = infer_location(state, courier)

            # ── Build invoice ─────────────────────────────────────────
            si_dict = {
                "doctype":                      "Sales Invoice",
                "customer":                     cust_name,
                "company":                      COMPANY,
                "posting_date":                 date,
                "set_posting_time":             1,
                "update_stock":                 0,
                "custom_online__offline":       "Online" if online else "Offline",
                "custom_state_type":            state,
                "custom_courier_charges_required": "No" if courier <= 0 else "Yes",
                "custom_location":              location,
                "cost_center":                  f"Main - {SUFFIX}",
                "debit_to":                     f"Debtors - {SUFFIX}",
                "income_account":               f"Sales - {SUFFIX}",
                "currency":                     "INR",
                "selling_price_list":           "Standard Selling",
                "ignore_pricing_rule":          1,
                "items": [{
                    "item_code":     item_code,
                    "item_name":     item_name,
                    "qty":           qty,
                    "rate":          rate,
                    "income_account": f"Sales - {SUFFIX}",
                    "expense_account": f"Cost of Goods Sold - {SUFFIX}",
                    "cost_center":   f"Main - {SUFFIX}",
                    "gst_treatment": "Taxable",
                }],
                "taxes": build_tax_rows(state, courier),
                "custom_courier_charges": [{
                    "courier_charges": courier,
                    "sgst": round(courier * 9 / 100, 2) if state == "Intra-State" else 0,
                    "cgst": round(courier * 9 / 100, 2) if state == "Intra-State" else 0,
                    "igst": round(courier * 18/ 100, 2) if state == "Inter-State" else 0,
                    "location": location,
                }],
            }

            if dry_run:
                # Just validate tax table is correct
                tax_desc = [t["description"] for t in si_dict["taxes"]]
                print(f"  [{start+idx+1}] {date} | {customer[:20]:20} | "
                      f"{item_name:15} x{qty} | ₹{rate} | {state[:5]} | "
                      f"courier ₹{courier} | taxes: {tax_desc}")
                ok += 1
                continue

            # ── Insert and submit ─────────────────────────────────────
            doc = frappe.get_doc(si_dict)
            doc.flags.ignore_permissions = True
            doc.insert()
            doc.submit()

            ok += 1
            results.append(f"  OK  vno {row['vno']:4} → {doc.name}  "
                           f"{date} {customer[:20]:20} {item_name}")

        except Exception as e:
            fail += 1
            msg = (f"  FAIL vno {row.get('vno','?'):4}  "
                   f"{date if 'date' in dir() else '?'} "
                   f"{customer if 'customer' in dir() else '?'} "
                   f"{item_name if 'item_name' in dir() else '?'}: "
                   f"{str(e)[:120]}")
            results.append(msg)
            print(msg)
            frappe.db.rollback()

    # ── Summary ───────────────────────────────────────────────────────
    print("\n" + "=" * 60)
    print(f"BATCH {start}–{start+len(batch)-1}  "
          f"OK {ok}  FAIL {fail}")
    if created_customers:
        print(f"Auto-created {len(created_customers)} customer(s): "
              + str(created_customers[:10]))
    if ok > 0:
        print(f"\nNext batch: start={start+len(batch)}")
    print("\nResults:")
    for r in results:
        print(r)